sys_script_fix.script:
function migrateSubscriptionEntitlements() {
	var grEnt = new GlideRecord('alm_license');
	grEnt.addQuery('product_type', 'IN', ['full', 'upgrade']);
	grEnt.addQuery('license_duration', '2'); // subscription
	grEnt.setWorkflow(false);
	grEnt.setValue('product_type', 'subscription');
	grEnt.updateMultiple();
}

migrateSubscriptionEntitlements();
